const lockConnectionAutoReminders = `-- name: LockConnectionAutoReminders :one
SELECT auto_reminders FROM external_connections WHERE id=$1::text FOR SHARE
`

// Share-locks a connection against its auto reminders switch and reads the
// switch, for the listener sweep's install.
func (q *Queries) LockConnectionAutoReminders(ctx context.Context, id string) (bool, error) {
	row := q.db.QueryRow(ctx, lockConnectionAutoReminders, id)
	var auto_reminders bool
	err := row.Scan(&auto_reminders)
	return auto_reminders, err
}

