const pruneProactiveShadowDivergences = `-- name: PruneProactiveShadowDivergences :exec
DELETE FROM proactive_shadow_divergences
WHERE tenant_id=$1::text AND owner_actor_id=$2::text
  AND id NOT IN (
    SELECT id FROM proactive_shadow_divergences
    WHERE tenant_id=$1::text AND owner_actor_id=$2::text
    ORDER BY created_at DESC, id DESC
    LIMIT $3::integer
  )
`

type PruneProactiveShadowDivergencesParams struct {
	TenantID     string `json:"tenant_id"`
	OwnerActorID string `json:"owner_actor_id"`
	Keep         int32  `json:"keep"`
}

// Only the latest divergences are shown, so older ones are dropped as new
// ones arrive.
func (q *Queries) PruneProactiveShadowDivergences(ctx context.Context, arg PruneProactiveShadowDivergencesParams) error {
	_, err := q.db.Exec(ctx, pruneProactiveShadowDivergences, arg.TenantID, arg.OwnerActorID, arg.Keep)
	return err
}

const upsertProactivePotentialItem = `-- name: UpsertProactivePotentialItem :execrows
INSERT INTO proactive_potential_items(id,tenant_id,owner_actor_id,content,source,source_key,reminded)
VALUES ($1::text,$2::text,$3::text,
        $4::text,$5::text,$6::text,$7::boolean)
ON CONFLICT (tenant_id,owner_actor_id,source,source_key) DO NOTHING
`

type UpsertProactivePotentialItemParams struct {
	ID           string `json:"id"`
	TenantID     string `json:"tenant_id"`
	OwnerActorID string `json:"owner_actor_id"`
	Content      string `json:"content"`
	Source       string `json:"source"`
	SourceKey    string `json:"source_key"`
	Reminded     bool   `json:"reminded"`
}

// A source item enters once a day, tracked or reminded; a repeat judgment is
// ignored.
func (q *Queries) UpsertProactivePotentialItem(ctx context.Context, arg UpsertProactivePotentialItemParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertProactivePotentialItem,
		arg.ID,
		arg.TenantID,
		arg.OwnerActorID,
		arg.Content,
		arg.Source,
		arg.SourceKey,
		arg.Reminded,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
